<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{ArrowRight,Boxes}from'lucide-vue-next';import{api,session}from'../api';const username=ref('admin'),email=ref(''),password=ref(''),error=ref(''),loading=ref(false),registering=ref(false),router=useRouter();async function submit(){loading.value=true;error.value='';try{if(registering.value){await api('/api/auth/register',{method:'POST',body:JSON.stringify({username:username.value,email:email.value,password:password.value})})}const r=await api<{token:string;must_change_password?:boolean}>('/api/auth/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});session.token=r.token;router.push(r.must_change_password?'/settings/account':'/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script>
<template><main class="login-page"><section class="login-brand"><div class="login-mark"><Boxes/></div><span>PRODUCT SERVER</span><h1>从产物到部署，<br>保持流程清晰。</h1><p>集中保存 CI 产物，以可视化工作流安全地交付到你的服务器。</p><div class="login-lines"><i></i><i></i><i></i></div></section><section class="card login-card"><div><span class="eyebrow">{{registering?'创建账号':'欢迎回来'}}</span><h2>{{registering?'注册 Product Server':'登录控制台'}}</h2><p>{{registering?'注册后即可创建或加入项目。':'使用你的账号继续。'}}</p></div><form @submit.prevent="submit"><label>用户名<input v-model="username" required autocomplete="username" minlength="3"></label><label v-if="registering">邮箱（可选）<input v-model="email" type="email" autocomplete="email"></label><label>密码<input v-model="password" type="password" required autofocus :autocomplete="registering?'new-password':'current-password'" minlength="8" maxlength="128"></label><p v-if="error" class="error">{{error}}</p><button class="btn login-submit" :disabled="loading">{{loading?'请稍候…':registering?'注册并登录':'登录'}}<ArrowRight/></button></form><button class="text-button" @click="registering=!registering;error=''">{{registering?'已有账号？返回登录':'没有账号？立即注册'}}</button><small>Product Server · 私有产物交付平台</small></section></main></template>
